const item = $('Buscar Tarea Pendiente').item.json;
const research = $json.stdout || '';

const systemPrompt = 'Sos un estratega de producto senior. Respondé en español, en formato markdown, con recomendaciones concretas y accionables, no genéricas.';
const userPrompt = `Basándote en esta investigación consolidada para el proyecto "${item.ProjectName}":\n\n${research}\n\nGenerá tres secciones separadas EXACTAMENTE por estos marcadores (sin texto adicional antes o después de cada marcador):\n\n===PRODUCT_STRATEGY===\n(Problema principal, usuario objetivo, propuesta de valor, diferenciadores, hipótesis clave)\n\n===BUSINESS_MODEL===\n(Modelo de negocio: cómo genera ingresos, estructura de costos, canales, métricas clave)\n\n===OPPORTUNITY_ANALYSIS===\n(Tamaño de oportunidad, riesgos principales, por qué ahora, por qué este equipo/enfoque)`;

const body = {
  model: 'openai/gpt-4o-mini',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{ json: { ...item, requestBody: JSON.stringify(body) } }];

const item = $('Buscar Tarea Pendiente').item.json;
const response = $json;
const content = response.choices?.[0]?.message?.content || '';
const usage = response.usage || {};

function extract(marker, nextMarker) {
  const start = content.indexOf(marker);
  if (start === -1) return '_No se pudo generar esta sección._';
  const from = start + marker.length;
  const end = nextMarker ? content.indexOf(nextMarker, from) : content.length;
  return content.slice(from, end === -1 ? content.length : end).trim();
}

const productStrategyMd = extract('===PRODUCT_STRATEGY===', '===BUSINESS_MODEL===');
const businessModelMd = extract('===BUSINESS_MODEL===', '===OPPORTUNITY_ANALYSIS===');
const opportunityAnalysisMd = extract('===OPPORTUNITY_ANALYSIS===', null);

const strategyMd = `# Product Strategy — ${item.ProjectName}\n\n${productStrategyMd}\n`;
const bmMd = `# Business Model — ${item.ProjectName}\n\n${businessModelMd}\n`;
const oaMd = `# Opportunity Analysis — ${item.ProjectName}\n\n${opportunityAnalysisMd}\n`;

const reportMd = `# Reporte de Etapa — AIQ-PF-04-ProductStrategy\n\n` +
  `**Proyecto:** ${item.ProjectName} (${item.Slug})\n` +
  `**Fecha:** ${new Date().toISOString()}\n` +
  `**Modelo usado:** ${response.model || 'desconocido'}\n` +
  `**Tokens:** entrada ${usage.prompt_tokens ?? '?'} / salida ${usage.completion_tokens ?? '?'}\n\n` +
  `## Archivos generados\n- strategy/product-strategy.md\n- strategy/business-model.md\n- strategy/opportunity-analysis.md\n\n` +
  `## Resumen\n${productStrategyMd.slice(0, 500)}${productStrategyMd.length > 500 ? '...' : ''}\n`;

return [{
  json: {
    ...item,
    strategyMdB64: Buffer.from(strategyMd, 'utf8').toString('base64'),
    bmMdB64: Buffer.from(bmMd, 'utf8').toString('base64'),
    oaMdB64: Buffer.from(oaMd, 'utf8').toString('base64'),
    reportMdB64: Buffer.from(reportMd, 'utf8').toString('base64')
  }
}];
